-- Incident war-room threads. Comments are always read within the owning organization and are
-- removed together with their incident. is_system marks lifecycle confirmations generated by
-- slash commands, which the UI renders differently from human messages.
CREATE TABLE incident_comments (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    incident_id BIGINT NOT NULL,
    organization_id BIGINT NOT NULL,
    user_id BIGINT NULL,
    text VARCHAR(2000) NOT NULL,
    is_system BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_incident_comments_incident
        FOREIGN KEY (incident_id) REFERENCES alert_incidents (id) ON DELETE CASCADE,
    INDEX idx_incident_comments_incident_created (incident_id, created_at),
    INDEX idx_incident_comments_organization_id (organization_id)
);
